insert into public.question_bank (code, lesson_id, type, level, content, answer_number, tolerance, unit, explanation, formula, remember, points, source, status, sort_order) values ('B2-04', (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 2), 'multiple_choice', 'van_dung', 'Một vật khối lượng 2 kg ở độ cao 3 m so với mặt đất. Chọn mốc thế năng tại mặt đất, thế năng của vật là', null, 0, null, 'Wt = P·h = 10·m·h = 10·2·3 = 60 J.', 'Wt = P·h = 10·m·h', null, 1, 'PHYSICS AI – câu hỏi mẫu', 'published', 4) on conflict (code) do update set lesson_id = excluded.lesson_id, type = excluded.type, level = excluded.level, content = excluded.content, answer_number = excluded.answer_number, tolerance = excluded.tolerance, unit = excluded.unit, explanation = excluded.explanation, formula = excluded.formula, remember = excluded.remember, sort_order = excluded.sort_order;
