insert into public.question_bank (code, lesson_id, type, level, content, answer_number, tolerance, unit, explanation, formula, remember, points, source, status, sort_order) values ('B2-05', (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 2), 'true_false', 'hieu', 'Một ô tô khối lượng 1 tấn chuyển động với tốc độ 10 m/s trên đoạn đường nằm ngang. Chọn mốc thế năng tại mặt đường.', null, 0, null, 'Áp dụng Wđ = ½mv² và Wt = 10mh với 1 tấn = 1000 kg.', null, null, 1, 'PHYSICS AI – câu hỏi mẫu', 'published', 5) on conflict (code) do update set lesson_id = excluded.lesson_id, type = excluded.type, level = excluded.level, content = excluded.content, answer_number = excluded.answer_number, tolerance = excluded.tolerance, unit = excluded.unit, explanation = excluded.explanation, formula = excluded.formula, remember = excluded.remember, sort_order = excluded.sort_order;
insert into public.question_subitems (question_id, label, content, is_true, explanation) values ((select id from public.question_bank where code = 'B2-05'), 'a', 'Ô tô có động năng.', true, 'Ô tô đang chuyển động nên có động năng.') on conflict (question_id, label) do update set content = excluded.content, is_true = excluded.is_true, explanation = excluded.explanation;
insert into public.question_subitems (question_id, label, content, is_true, explanation) values ((select id from public.question_bank where code = 'B2-05'), 'b', 'Động năng của ô tô là 50 000 J.', true, 'Wđ = ½·1000·10² = 50 000 J.') on conflict (question_id, label) do update set content = excluded.content, is_true = excluded.is_true, explanation = excluded.explanation;
