insert into public.question_bank (code, lesson_id, type, level, content, answer_number, tolerance, unit, explanation, formula, remember, points, source, status, sort_order) values ('B2-06', (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 2), 'short_answer', 'van_dung', 'Một quả bóng khối lượng 0,4 kg bay với tốc độ 5 m/s. Động năng của quả bóng là bao nhiêu jun?', 5, 0.01, 'J', 'Wđ = ½·0,4·5² = 0,2·25 = 5 J.', 'Wđ = ½·m·v²', null, 1, 'PHYSICS AI – câu hỏi mẫu', 'published', 6) on conflict (code) do update set lesson_id = excluded.lesson_id, type = excluded.type, level = excluded.level, content = excluded.content, answer_number = excluded.answer_number, tolerance = excluded.tolerance, unit = excluded.unit, explanation = excluded.explanation, formula = excluded.formula, remember = excluded.remember, sort_order = excluded.sort_order;
insert into public.question_bank (code, lesson_id, type, level, content, answer_number, tolerance, unit, explanation, formula, remember, points, source, status, sort_order) values ('B2-07', (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 2), 'short_answer', 'van_dung', 'Một quyển sách khối lượng 0,5 kg đặt trên giá sách cao 1,8 m so với sàn nhà. Chọn mốc thế năng tại sàn, thế năng của quyển sách là bao nhiêu jun?', 9, 0.01, 'J', 'Wt = 10·m·h = 10·0,5·1,8 = 9 J.', 'Wt = 10·m·h', null, 1, 'PHYSICS AI – câu hỏi mẫu', 'published', 7) on conflict (code) do update set lesson_id = excluded.lesson_id, type = excluded.type, level = excluded.level, content = excluded.content, answer_number = excluded.answer_number, tolerance = excluded.tolerance, unit = excluded.unit, explanation = excluded.explanation, formula = excluded.formula, remember = excluded.remember, sort_order = excluded.sort_order;
