insert into public.question_bank (code, lesson_id, type, level, content, answer_number, tolerance, unit, explanation, formula, remember, points, source, status, sort_order) values ('B3-05', (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 3), 'true_false', 'van_dung', 'Ném một vật khối lượng 0,2 kg thẳng đứng lên từ mặt đất với tốc độ 10 m/s. Bỏ qua lực cản, chọn mốc thế năng tại mặt đất.', null, 0, null, 'Áp dụng bảo toàn cơ năng W = Wđ + Wt = hằng số.', null, null, 1, 'PHYSICS AI – câu hỏi mẫu', 'published', 5) on conflict (code) do update set lesson_id = excluded.lesson_id, type = excluded.type, level = excluded.level, content = excluded.content, answer_number = excluded.answer_number, tolerance = excluded.tolerance, unit = excluded.unit, explanation = excluded.explanation, formula = excluded.formula, remember = excluded.remember, sort_order = excluded.sort_order;
