insert into public.question_bank (code, lesson_id, type, level, content, answer_number, tolerance, unit, explanation, formula, remember, points, source, status, sort_order) values ('B16-07', (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 16), 'short_answer', 'van_dung', 'Cần đốt cháy hoàn toàn bao nhiêu kg khí đốt (q = 44·10⁶ J/kg) để thu được nhiệt lượng 88·10⁶ J?', 2, 0.01, 'kg', 'm = Q/q = 88·10⁶ / 44·10⁶ = 2 kg.', 'Q = q·m', null, 1, 'PHYSICS AI – câu hỏi mẫu', 'published', 7) on conflict (code) do update set lesson_id = excluded.lesson_id, type = excluded.type, level = excluded.level, content = excluded.content, answer_number = excluded.answer_number, tolerance = excluded.tolerance, unit = excluded.unit, explanation = excluded.explanation, formula = excluded.formula, remember = excluded.remember, sort_order = excluded.sort_order;
